import * as ecs from "@8thwall/ecs";

import { gameData } from "../core/game-data";
import { GameState } from "../core/game-state";
import { GAME_CONFIG } from "../core/constants";

import { collectible } from "../components/collectible";

import { addScore } from "./score-system";


// Optional replacement spawn
import { spawnReplacementCollectible } from "./collectible-spawn-system";



// --------------------------------------------------
// Collectible Pickup System
//
// Handles:
// - distance detection
// - scoring
// - removing collected item
// - spawning replacement item
// --------------------------------------------------


export function collectibleSystem(
  world: ecs.World
) {


  //---------------------------------------
  // No truck
  //---------------------------------------

  if(gameData.truckEid === null)
    return;



  //---------------------------------------
  // Only during gameplay
  //---------------------------------------

  if(gameData.state !== GameState.DRIVING)
    return;



  const truckPos =
    world.transform.getWorldPosition(
      gameData.truckEid
    );



  //---------------------------------------
  // Check collectibles
  //---------------------------------------

  for(
    let i = gameData.collectibleEids.length - 1;
    i >= 0;
    i--
  )
  {


    const collectibleEid =
      gameData.collectibleEids[i];



    //---------------------------------------
    // Entity already gone
    //---------------------------------------

    if(!collectible.has(world, collectibleEid))
    {

      gameData.collectibleEids.splice(
        i,
        1
      );

      continue;

    }



    const itemPos =
      world.transform.getWorldPosition(
        collectibleEid
      );



    const dx =
      truckPos.x - itemPos.x;


    const dy =
      truckPos.y - itemPos.y;


    const dz =
      truckPos.z - itemPos.z;



    const distance =
      Math.sqrt(
        dx*dx +
        dy*dy +
        dz*dz
      );



    //---------------------------------------
    // Pickup radius
    //---------------------------------------

    if(
      distance <
      GAME_CONFIG.COLLECTION_RADIUS
    )
    {


      const item =
        collectible.get(
          world,
          collectibleEid
        );



      console.log(
        "[COLLECTED]",
        {
          eid:collectibleEid,
          type:item.type,
          value:item.value
        }
      );



      //---------------------------------------
      // Score
      //---------------------------------------

      addScore(
        item.value
      );



      //---------------------------------------
      // Remove
      //---------------------------------------

      world.deleteEntity(
        collectibleEid
      );



      gameData.collectibleEids.splice(
        i,
        1
      );



      //---------------------------------------
      // Replace after delay
      //---------------------------------------

      setTimeout(()=>{

        if(
          gameData.state === GameState.DRIVING
        )
        {

          spawnReplacementCollectible(
            world
          );

        }

      },1000);



    }


  }


}
